def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            version_part, build = v.rsplit('+', 1)
        else:
            version_part = v
            build = None

        # Split pre-release
        if '-' in version_part:
            base, prerelease = version_part.split('-', 1)
        else:
            base = version_part
            prerelease = None

        # Parse base version
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(v, index):
        major, minor, patch, prerelease_identifiers = parse_version(v)
        # Version without pre-release sorts after version with pre-release
        # So we use (major, minor, patch, has_prerelease, prerelease_identifiers, index)
        # where has_prerelease is 1 if no prerelease (sorts later), 0 if has prerelease
        has_prerelease = 0 if prerelease_identifiers else 1
        return (major, minor, patch, has_prerelease, prerelease_identifiers, index)

    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=lambda x: sort_key(x[0], x[1]))
    return [v for v, _ in sorted_versions]

